const byJapanese=new Map(translations);
const byEnglish=new Map(translations.map(([ja,en])=>[en,ja]));
let language=globalThis.localStorage?.getItem('pve.iphone.language')==='en'?'en':'ja';

export function currentLanguage(){return language}
export function setLanguage(next){language=next==='en'?'en':'ja';globalThis.localStorage?.setItem('pve.iphone.language',language);if(globalThis.document)document.documentElement.lang=language;return language}
