function exactTranslation(body,target){if(target==='en'){if(byJapanese.has(body))return byJapanese.get(body);if(!/[ぁ-んァ-ヶ一-龠]/.test(body))return body;for(const [pattern,replace] of dynamicEnglish)if(pattern.test(body))return body.replace(pattern,replace);const placement=body.match(/^([VA]\d)へ配置$/),visibility=body.match(/^(F\/T\d|V\d)を非表示$/),overlayVisibility=body.match(/^FX・TEXT (\d)を非表示$/),mute=body.match(/^(A\d)をミュート$/),volume=body.match(/^([VA]\d)の音量$/),uses=body.match(/^タイムライン (\d+)箇所$/),approx=body.match(/^約 (.+)$/),aspect=body.match(/^編集 (.+) → 出力 (.+)。画面比率の変換を確認してください。$/);if(placement)return`Place on ${placement[1]}`;if(visibility)return`Hide ${visibility[1]}`;if(overlayVisibility)return`Hide F/T${overlayVisibility[1]}`;if(mute)return`Mute ${mute[1]}`;if(volume)return`${volume[1]} volume`;if(uses)return`Timeline · ${uses[1]} ${uses[1]==='1'?'use':'uses'}`;if(approx)return`Approx. ${approx[1]}`;if(aspect)return`Editing ${aspect[1]} → output ${aspect[2]}. Review the aspect-ratio conversion.`;return byJapanese.get(body)??body}const placement=body.match(/^Place on ([VA]\d)$/),visibility=body.match(/^Hide (F\/T\d|V\d)$/),mute=body.match(/^Mute (A\d)$/),volume=body.match(/^([VA]\d) volume$/),uses=body.match(/^Timeline · (\d+) uses?$/);if(placement)return`${placement[1]}へ配置`;if(visibility)return`${visibility[1]}を非表示`;if(mute)return`${mute[1]}をミュート`;if(volume)return`${volume[1]}の音量`;if(uses)return`タイムライン ${uses[1]}箇所`;return byEnglish.get(body)??body}
export function translate(value,target=language){const source=String(value??''),match=source.match(/^(\s*)([\s\S]*?)(\s*)$/),lead=match?.[1]||'',body=match?.[2]||'',trail=match?.[3]||'',decorated=body.match(/^([＋✧⠿△]\s+)(.+)$/);if(decorated){const translated=translate(decorated[2],target);if(translated!==decorated[2])return lead+decorated[1]+translated+trail}const direct=exactTranslation(body,target);if(direct!==body)return lead+direct+trail;const sentences=target==='en'?body.match(/[^。！？]+[。！？]?/g)||[]:body.match(/\s*[^.!?]+[.!?]?/g)?.map(part=>part.trim())||[];if(sentences.length>1){const translated=[];let changed=false;for(let i=0;i<sentences.length;){let found=false;if(target==='en')for(let end=sentences.length;end>i;end--){const phrase=sentences.slice(i,end).join('').trim(),result=exactTranslation(phrase,target);if(result!==phrase){translated.push(result);changed=true;i=end;found=true;break}}if(!found){const phrase=sentences[i].trim(),result=exactTranslation(phrase,target);translated.push(result);changed ||= result!==phrase;i++}}if(changed)return lead+translated.join(target==='en'?' ':'')+trail}return source}
const textSources=new WeakMap(),attributeSources=new WeakMap();
const excluded='[data-no-i18n],.media-name,.text-chip,.text-item,.project-option:not([data-relink-candidate]),[data-relink-candidate] strong,script,style,textarea,[contenteditable="true"]';
function translateNode(node){
 if(node.parentElement?.closest(excluded))return;
 const value=node.nodeValue,previous=textSources.get(node),source=previous&&value===previous.rendered?previous.source:value;
 const rendered=language==='ja'?source:translate(source,'en');textSources.set(node,{source,rendered});if(rendered!==value)node.nodeValue=rendered;
}
function translateAttributes(element){
 if(element.closest?.('[data-no-i18n],.text-item,.media-name'))return;
 let records=attributeSources.get(element);if(!records){records=new Map();attributeSources.set(element,records)}
 for(const name of ['title','aria-label','placeholder'])if(element.hasAttribute(name)){
  const value=element.getAttribute(name),previous=records.get(name),source=previous&&value===previous.rendered?previous.source:value;
  const rendered=language==='ja'?source:translate(source,'en');records.set(name,{source,rendered});if(rendered!==value)element.setAttribute(name,rendered);
 }
}
export function translateDOM(root=document){
 document.documentElement.lang=language;
 if(root.nodeType===3){translateNode(root);return}
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())translateNode(node);
 if(root.nodeType===1)translateAttributes(root);
 for(const element of root.querySelectorAll?.('[title],[aria-label],[placeholder]')||[])translateAttributes(element);
}
export function observeTranslations(root=document.body){
 const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')translateNode(record.target);else if(record.type==='attributes')translateAttributes(record.target);else for(const node of record.addedNodes)translateDOM(node)}});
 observer.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','placeholder']});return observer;
}
